function fuseInterpolate(keys, x, prop) {
  if (x <= keys[0].t) return keys[0][prop] || 0;
  const last = keys.length - 1;
  if (x >= keys[last].t) return keys[last][prop] || 0;
  const secant = i => ((keys[i + 1][prop] || 0) - (keys[i][prop] || 0)) / (keys[i + 1].t - keys[i].t);
  const slope = i => {
    if (i === 0) return secant(0);
    if (i === last) return secant(last - 1);
    const a = secant(i - 1), b = secant(i);
    if (a * b <= 0) return 0;
    const ha = keys[i].t - keys[i - 1].t, hb = keys[i + 1].t - keys[i].t;
    const wa = 2 * hb + ha, wb = hb + 2 * ha;
    return (wa + wb) / (wa / a + wb / b);
  };
  const i = keys.findIndex((k, j) => j < last && x <= keys[j + 1].t);
  const a = keys[i], b = keys[i + 1], h = b.t - a.t, u = (x - a.t) / h;
  return (2*u**3 - 3*u*u + 1) * (a[prop] || 0) + (u**3 - 2*u*u + u) * h * slope(i)
    + (-2*u**3 + 3*u*u) * (b[prop] || 0) + (u**3 - u*u) * h * slope(i + 1);
}

function fuselageStationX(geom, station) {
  const length=geom.fuselage_length;
  const layout=geom.fuselage_layout_length || length;
  const aft=Math.max(0,(station-.66)/.34);
  return station*layout+(length-layout)*aft*aft*(3-2*aft);
}

function goliathSections(geom) {
  const totalLen = geom.fuselage_length;
  const baseScale = totalLen / GOLIATH_BODY_LENGTH;
  const cabin = geom.cabin_dimensions_preset === 'atlas';
  const widthScale = (cabin ? geom.fuselage_max_width/(.11733987*GOLIATH_BODY_LENGTH/.8) : baseScale)
    * (geom.fuse_width_scale || 1);
  const heightScale = (cabin ? geom.fuselage_max_height/(.13708695*GOLIATH_BODY_LENGTH/.8) : baseScale)
    * (geom.fuse_height_scale || 1);
  const nCirc = 64;
  const sections = GOLIATH_SECTIONS.map(([station, centerY, ...radii]) =>
    Array.from({length: nCirc}, (_, index) => {
      const angle = index * 2 * Math.PI / nCirc;
      const sample = index >= 16 && index <= 48 ? index : (32 - index + nCirc) % nCirc;
      const radius = radii[sample - 16];
      return new THREE.Vector3(
        fuselageStationX(geom,station),
        (centerY + Math.sin(angle) * radius) * heightScale,
        Math.cos(angle) * radius * widthScale
      );
    })
  );
  return {sections, nCirc, totalLen};
}

function atlasEditableKeys(geom, detailed = false) {
  const {sections} = goliathSections(geom);
  const count = detailed ? sections.length : 18;
  return Array.from({length: count}, (_, i) => {
    const ring = sections[Math.round(i * (sections.length - 1) / (count - 1))];
    const ys = ring.map(point => point.y);
    const zs = ring.map(point => point.z);
    const min = Math.min(...ys), max = Math.max(...ys);
    return {t: ring[0].x, w: Math.max(...zs) - Math.min(...zs), h: max - min, cy: (min + max) / 2};
  });
}

function akinPodLength(g) {
  return Math.min(g.tail_x_pos-.15, Math.max(.59*g.fuselage_length,g.wing_x_pos+g.root_chord+.018));
}

function akinTubeHeight(g) {
  const height = g.fuselage_max_height*(g.cabin_dimensions_preset==='akin'?1:FUSELAGE_PRESETS.akin.height)
    *(g.fuse_height_scale||1);
  return Math.min(-.035, FUSELAGE_PRESETS.akin.stations.at(-1)[3]*height - (g.motor_mount?.propDiameter || 152)/2000-.016);
}

function presetFuseKeys(geom, id) {
  const preset = FUSELAGE_PRESETS[id];
  if (!preset || id === 'atlas') return atlasEditableKeys(geom);
  if(id==='vtol5')return preset.stations.map(([t,w,h,cy])=>({t:t*(geom.fuselage_length||1),w:w*(geom.fuselage_max_width||.18),h:h*(geom.fuselage_max_height||.14),cy:cy*(geom.fuselage_max_height||.14)}));
  if(id==='vtol'){
    const length=geom.fuselage_length||1.2;
    const scale=length/1.2;
    return preset.stations.map(([t,w,h,cy])=>({t:t*length,w:w*.17*scale,h:h*.11*scale,cy:cy*.11*scale}));
  }
  const cabin = geom.cabin_dimensions_preset === id;
  const width = geom.fuselage_max_width * (cabin ? 1 : preset.width) * (geom.fuse_width_scale || 1);
  const height = geom.fuselage_max_height * (cabin ? 1 : preset.height) * (geom.fuse_height_scale || 1);
  return preset.stations.map(([t, w, h, cy]) => ({
    t: id==='akin' ? t*akinPodLength(geom) : fuselageStationX(geom,t), w: w * width, h: h * height, cy: cy * height,
  }));
}

function loftFuselage(keys, exponent = 2, nLong = 120, upperTaper = 0) {
  const ordered = [...new Map(keys.filter(s => [s.t, s.w, s.h].every(Number.isFinite))
    .map(s => [s.t, { ...s, w: Math.max(.0001, s.w), h: Math.max(.0001, s.h) }])).values()]
    .sort((a, b) => a.t - b.t);
  if (ordered.length < 2) return { sections: [], nCirc: 64, totalLen: 0 };
  const nCirc = 64;
  const start = ordered[0].t, end = ordered[ordered.length - 1].t;
  const positions = [...new Set([...ordered.map(s => s.t), ...Array.from({length: nLong + 1}, (_, i) => start + (end - start) * i / nLong)]
    .map(x => Math.round(x * 1e9) / 1e9))].sort((a,b) => a-b);
  const sections = positions.map(x => {
    const w = fuseInterpolate(ordered, x, 'w') / 2;
    const h = fuseInterpolate(ordered, x, 'h') / 2;
    const cy = fuseInterpolate(ordered, x, 'cy');
    const u = (x - start) / (end - start);
    const n = 2 + (exponent - 2) * Math.sin(Math.PI * u) ** 2;
    const fade = Math.max(0, Math.min(1, (.56 - u) / .15));
    const taper = upperTaper * fade * fade * (3 - 2 * fade);
    return Array.from({length:nCirc}, (_, j) => {
      const angle = j / nCirc * Math.PI * 2, c = Math.cos(angle), s = Math.sin(angle);
      const shoulder = 1 - taper * Math.max(0, s) ** 2;
      return new THREE.Vector3(x, cy + h * Math.sign(s) * Math.abs(s) ** (2 / n), w * shoulder * Math.sign(c) * Math.abs(c) ** (2 / n));
    });
  });
  return { sections, nCirc, totalLen: end - start };
}

function libraryFuselageSections(geom) {
  const id = FUSELAGE_PRESETS[geom.fuse_preset] ? geom.fuse_preset : 'atlas';
  if (id === 'atlas') return motorSizedFuselageSections(geom, goliathSections(geom));
  const preset=FUSELAGE_PRESETS[id];
  const result=loftFuselage(presetFuseKeys(geom,id),preset.exponent,id==='vtol5'?127:120,preset.upperTaper);
  if(id==='vtol5'){
    const keys=presetFuseKeys(geom,id), length=geom.fuselage_length||1;
    const roofKeys=keys.map((k,i)=>({...k,top:[.22,.58,.83,.94,.88,.72,.55,.46][i]*(geom.fuselage_max_height||.14)/2}));
    const smooth=u=>{u=Math.max(0,Math.min(1,u));return 6*u**5-15*u**4+10*u**3;};
    for(const ring of result.sections){const x=ring[0].x,t=x/length,cy=fuseInterpolate(keys,x,'cy');
      const roof=fuseInterpolate(roofKeys,x,'top')/(fuseInterpolate(keys,x,'h')/2);
      const u=Math.max(0,Math.min(1,(t-.80)/.20)), blend=smooth(u);
      const diameter=(geom.motor_mount?.motorDiameter||geom.penta_motor_diameter||28)/1000;
      for(const p of ring){if(p.y>cy)p.y=cy+(p.y-cy)*roof;
        const radius=Math.hypot(p.y,p.z), target=diameter/(2*Math.max(radius,1e-12));
        p.y=p.y*(1-blend)+p.y*target*blend;p.z=p.z*(1-blend)+p.z*target*blend;
      }
    }
  }
  return motorSizedFuselageSections(geom,result);
}

function motorPlateRadius(geom, settings) {
  if (settings.motorLayout === 'rear' && geom.tail_booms) return settings.motorDiameter / 2;
  const gap = settings.clearance ?? .3;
  const y = (settings.motorSpacingY ?? 16) / 2, z = (settings.motorSpacingZ ?? 19) / 2;
  const bolt = settings.motorPattern === 'rectangle' ? Math.hypot(y, z) : Math.max(y, z);
  return Math.max(settings.motorDiameter / 2 + 3, bolt + ((settings.motorScrew ?? 3) + gap) / 2 + 3,
                  ((settings.motorBore ?? 8) + gap) / 2 + (settings.motorWire ?? 6) + 4);
}

function motorSizedFuselageSections(geom,result) {
  if(['vtol','vtol5'].includes(geom.fuse_preset))return result;
  const motor=geom.motor_mount;
  if(motor?.motorLayout!=='rear' || !(motor.motorDiameter>0) || !result.sections.length)return result;
  const sections=result.sections,end=sections[sections.length-1],radius=motorPlateRadius(geom, motor)/1000;
  const cy=end.reduce((s,p)=>s+p.y,0)/end.length,cz=end.reduce((s,p)=>s+p.z,0)/end.length;
  if(end.every(p=>Math.abs(Math.hypot(p.y-cy,p.z-cz)-radius)<.00001))return result;
  const first=sections[0][0].x,last=end[0].x;
  const start=first+(geom.fuse_preset==='akin'?.976:geom.tail_booms?.8:.92)*(last-first);
  for(const ring of sections)for(const p of ring) {
    const u=Math.max(0,Math.min(1,(p.x-start)/(last-start))),blend=u*u*(3-2*u);
    const dy=p.y-cy,dz=p.z-cz,n=Math.hypot(dy,dz);
    if(n>0){p.y+=blend*(cy+radius*dy/n-p.y);p.z+=blend*(cz+radius*dz/n-p.z);}
  }
  return result;
}

function fusePresetThumbnail(id) {
  const keys = id === 'atlas'
    ? atlasEditableKeys({fuselage_length: 1}, true).map(({t,w,h,cy}) => ({t,w,h:h*5,cy:cy*5}))
    : FUSELAGE_PRESETS[id].stations.map(([t,w,h,cy]) => ({t,w,h,cy}));
  const top = [], bottom = [];
  for (let i = 0; i <= 60; i++) {
    const x = i / 60, h = fuseInterpolate(keys, x, 'h'), cy = fuseInterpolate(keys,x,'cy');
    top.push(`${12 + x*216},${44 - (cy + h/2)*49}`);
    bottom.unshift(`${12 + x*216},${44 - (cy - h/2)*49}`);
  }
  return `<svg viewBox="0 0 240 84" aria-hidden="true"><path class="fuse-datum" d="M8 44H232"/><path class="fuse-silhouette" d="M${top.join(' L')} L${bottom.join(' L')}Z"/></svg>`;
}

